import{_ as s,o as n,c as e,ai as i}from"./chunks/framework.Ba-VnP44.js";const b=JSON.parse('{"title":"01 项目准备","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/dev-spec/02-lifecycle/project-prep.md","filePath":"ai/productivity/dev-spec/02-lifecycle/project-prep.md"}'),l={name:"ai/productivity/dev-spec/02-lifecycle/project-prep.md"};function t(p,a,r,c,d,o){return n(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="_01-项目准备" tabindex="-1">01 项目准备 <a class="header-anchor" href="#_01-项目准备" aria-label="Permalink to “01 项目准备”">​</a></h1><blockquote><p>第二层 · 开发生命周期的起点。让 AI 先懂项目、定边界，准备到「能说清改哪里、影响谁、不能碰什么」就够了，不要先建一堆文档。</p></blockquote><h2 id="什么时候用" tabindex="-1">什么时候用 <a class="header-anchor" href="#什么时候用" aria-label="Permalink to “什么时候用”">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>怎么做</th></tr></thead><tbody><tr><td>全新项目，还没开始写</td><td>先定边界，再让 AI 写代码</td></tr><tr><td>已有脚手架，尚未正式开发</td><td>检查现状，补项目约定</td></tr><tr><td>接手别人的项目</td><td>只读理解，建立最小上下文</td></tr><tr><td>AI 经常理解错、改错地方</td><td>补上下文和规则，不必重做接入</td></tr><tr><td>改文案、小调整</td><td>跳过，直接派活</td></tr></tbody></table><p>准备深度由任务决定：简单修改看当前文件即可；小 Bug 要一条调用链 + 复现条件；普通功能要模块地图 + 影响范围；复杂功能或老项目才做完整接入。</p><h2 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to “操作步骤”">​</a></h2><h3 id="新项目-先定边界" tabindex="-1">新项目：先定边界 <a class="header-anchor" href="#新项目-先定边界" aria-label="Permalink to “新项目：先定边界”">​</a></h3><ol><li>说清项目目标、用户和核心功能。</li><li>检查已有文件，确认技术栈与运行环境，不覆盖已有内容。</li><li>定下开发、构建、测试命令，并实际跑通一次。</li><li>定代码规范、命名分层和禁改边界。</li><li>只创建当前阶段需要的规则和资料（见第一层 <a href="/my-vitepress-site/ai/productivity/dev-spec/01-foundation/project-context.html">Project Context</a>、<a href="/my-vitepress-site/ai/productivity/dev-spec/01-foundation/rules.html">Rules</a>）。</li></ol><p><strong>边界 → 结构 → 代码</strong>。顺序反了，AI 会用「它认为合理」的结构替你做架构决策，而那个决策只活在那轮对话里。</p><h3 id="老项目-先理解现状" tabindex="-1">老项目：先理解现状 <a class="header-anchor" href="#老项目-先理解现状" aria-label="Permalink to “老项目：先理解现状”">​</a></h3><p>按几块看，边看边记来源：结构与技术栈、启动构建测试方式、核心业务模块与调用、关键接口与数据实体、已有规则与规范、已知问题与风险、与当前任务相关的代码位置。</p><p>汇成一份简短的接入报告，每条标「已确认 / 待确认 / 人工补充」（详见 <a href="/my-vitepress-site/ai/productivity/dev-spec/01-foundation/project-context.html">Project Context</a>）。</p><p>保护边界（突破前要说明原因并取得同意）：</p><ul><li>不擅自重构架构、改接口签名、升级依赖版本。</li><li>不批量格式化无关文件。</li><li>不把推测出来的业务规则当成真实规则。</li><li>不删已有功能，不改生产数据或执行不可逆操作。</li></ul><h3 id="什么时候可以开始开发" tabindex="-1">什么时候可以开始开发 <a class="header-anchor" href="#什么时候可以开始开发" aria-label="Permalink to “什么时候可以开始开发”">​</a></h3><ol><li>知道项目是什么。</li><li>知道怎么启动、编译、测试。</li><li>知道开发要遵守哪些规则。</li><li>当前任务相关信息能继续获取。</li><li>未确认的信息已明确标注。</li></ol><p>不需要等整个项目完全理解。新功能只需在开始该任务前补对应业务上下文。</p><h2 id="可复制提示词" tabindex="-1">可复制提示词 <a class="header-anchor" href="#可复制提示词" aria-label="Permalink to “可复制提示词”">​</a></h2><details><summary><strong>新项目初始化</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>现在准备开始一个新项目，请协助初始化，但暂时不要大规模编写业务代码。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第一步：确认项目要解决什么问题、主要用户是谁、核心功能、技术选型和开发约束。信息够就不要重复问，有关键缺失一次性列出。</span></span>
<span class="line"><span>第二步：检查当前目录，看是否已有项目文件、脚手架、Git 仓库、规则文件、必要依赖。不要覆盖或删除已有内容。</span></span>
<span class="line"><span>第三步：提出初始化方案，包括推荐目录结构、技术栈与依赖、开发/构建/测试命令、必要项目规则、当前阶段要创建的文件。</span></span>
<span class="line"><span>第四步：只创建当前真正需要的内容，不预建大量空文档，不为使用 Agent、Skill、MCP 强行加配置。</span></span>
<span class="line"><span>第五步：在我确认后再执行初始化和环境检查。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>报告已完成的初始化内容、目录结构、技术栈、开发测试命令、未解决问题和下一步建议。</span></span>
<span class="line"><span>不要把未确认的技术选型写成既定事实，不要执行未经确认的高风险操作。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div></details><details><summary><strong>老项目接管</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>你现在需要接管一个已有项目。本轮只读分析，建立后续开发所需的上下文。</span></span>
<span class="line"><span>暂时不要修改任何业务代码、不要重构、不要安装新依赖。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>按顺序检查：技术栈及版本、前后端架构、模块划分、目录结构；如何启动构建测试、是否有数据库和 Docker；核心业务模块、模块间调用、关键接口、重要数据实体、第三方集成；已有规则文件和代码规范；哪些模块不能随意改、哪些操作影响生产数据、已知问题、代码里查不到的信息。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>输出项目接入报告，每项标注：已确认（有证据）/ 待确认 / 人工补充。</span></span>
<span class="line"><span>约束：不扫依赖和生成目录，不逐个文件通读，不把猜测当事实，项目较大时先给整体地图再深入重要模块。</span></span>
<span class="line"><span>最后说明：是否具备开发条件，开始新功能还缺什么信息，哪些建议写入规则。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div></details><h2 id="验收要点" tabindex="-1">验收要点 <a class="header-anchor" href="#验收要点" aria-label="Permalink to “验收要点”">​</a></h2><ul><li>[ ] 新项目命令已实际跑通；老项目有带来源的接入报告。</li><li>[ ] 五问能答上：改哪几个文件、谁受影响、涉及哪张表哪个接口、现有实现为什么这么写、哪些地方不能碰。</li><li>[ ] 禁改区和安全边界写明，并同步进规则。</li><li>[ ] 推测都在「待确认」里，没有「应该是 / 一般是」。</li><li>[ ] 没有架构级改动，没有无意义的空文档。</li></ul><p>下一步进入 <a href="/my-vitepress-site/ai/productivity/dev-spec/02-lifecycle/requirement-analysis.html">02 需求分析</a>。第三层的安全与变更控制从这一阶段起就同步生效。</p>`,23)])])}const u=s(l,[["render",t]]);export{b as __pageData,u as default};
